"""Bilingual subtitle output: English on top, Chinese below (or English only)."""
from __future__ import annotations

import re
import textwrap
from pathlib import Path

from .schemas import Cue

ASS_HEADER = """[Script Info]
; Generated by news/subs.py
ScriptType: v4.00+
PlayResX: {width}
PlayResY: {height}
WrapStyle: 2
ScaledBorderAndShadow: yes

[V4+ Styles]
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
Style: SubEn,Arial,56,&H00FFFFFF,&H000000FF,&H00000000,&H00000000,0,0,0,0,100,100,0,0,1,4,2,2,90,90,{margin_en},1
Style: SubZh,Microsoft YaHei,46,&H00FFFFFF,&H000000FF,&H00000000,&H00000000,0,0,0,0,100,100,0,0,1,4,2,2,80,80,{margin_zh},1

[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
"""

CJK_RE = re.compile(r"[㐀-鿿]")


def fmt_ass(ms: int) -> str:
    ms = max(0, int(ms))
    cs = int(round(ms / 10))
    hours, rem = divmod(cs, 360_000)
    minutes, rem = divmod(rem, 6_000)
    seconds, centis = divmod(rem, 100)
    return f"{hours:d}:{minutes:02d}:{seconds:02d}.{centis:02d}"


def _esc(text: str) -> str:
    return text.replace("\\", "\\\\").replace("{", "(").replace("}", ")")


def _wrap_en(text: str, width: int = 50, max_lines: int = 3) -> list[str]:
    lines = textwrap.wrap(text, width=width, break_long_words=False,
                          break_on_hyphens=False) or [text]
    if len(lines) > max_lines:
        lines = lines[:max_lines - 1] + [" ".join(lines[max_lines - 1:])]
    return lines


def _wrap_zh(text: str, width: int = 20, max_lines: int = 3) -> list[str]:
    if len(text) <= width:
        return [text]
    lines: list[str] = []
    rest = text
    while len(rest) > width and len(lines) < max_lines - 1:
        window = rest[:width]
        cut = max(window.rfind(p) for p in "，。；：、,.!?;:") + 1
        if cut < width // 2:
            cut = width
        lines.append(rest[:cut].strip())
        rest = rest[cut:].strip()
    if rest:
        lines.append(rest)
    return lines


def ass_text(text_en: str, text_zh: str = "") -> tuple[str, str]:
    en = "\\N".join(_esc(line) for line in _wrap_en(text_en))
    zh = "\\N".join(_esc(line) for line in _wrap_zh(text_zh)) if text_zh else ""
    return en, zh


def write_ass(cues: list[Cue], path: str | Path, *, width: int = 1920, height: int = 1080,
              margin_en: int = 110, margin_zh: int = 40) -> None:
    lines = [ASS_HEADER.format(width=width, height=height,
                               margin_en=margin_en, margin_zh=margin_zh)]
    for cue in cues:
        if cue.end_ms <= cue.start_ms:
            continue
        en, zh = ass_text(cue.text_en, cue.text_zh)
        if en:
            lines.append(
                f"Dialogue: 0,{fmt_ass(cue.start_ms)},{fmt_ass(cue.end_ms)},SubEn,,0,0,0,,{en}"
            )
        if zh:
            lines.append(
                f"Dialogue: 0,{fmt_ass(cue.start_ms)},{fmt_ass(cue.end_ms)},SubZh,,0,0,0,,{zh}"
            )
    Path(path).write_text("\n".join(lines) + "\n", encoding="utf-8")


def fmt_srt(ms: int) -> str:
    ms = max(0, int(ms))
    hours, rem = divmod(ms, 3_600_000)
    minutes, rem = divmod(rem, 60_000)
    seconds, millis = divmod(rem, 1000)
    return f"{hours:02d}:{minutes:02d}:{seconds:02d},{millis:03d}"


def write_srt(cues: list[Cue], path: str | Path) -> None:
    blocks: list[str] = []
    for idx, cue in enumerate(cues, start=1):
        text = cue.text_en
        if cue.text_zh:
            text += "\n" + cue.text_zh
        blocks.append(f"{idx}\n{fmt_srt(cue.start_ms)} --> {fmt_srt(cue.end_ms)}\n{text}\n")
    Path(path).write_text("\n".join(blocks), encoding="utf-8")
